function messageAppliesTo(m, user) {
    if (m.recipientType === "all") return true;
    if (m.recipientType === "position") return (m.recipientPosition || "") === user.role;
    if (m.recipientType === "individual") return (m.recipientIds || []).includes(user.id);
    return false;
}
